import type { Tokens } from '../tokens';

/** First line of every generated file. */
export const BANNER =
  '/* Generated by @webatlas/theme from tokens.json. Do not edit; run npm run generate:theme. */';

/** One custom-property declaration per token, in tokens.json order. */
export type Declaration = [name: string, value: string];

/** Every token as [group, key, CSS value], with px/ms units applied. */
export function cssValues(t: Tokens): Array<[group: keyof Tokens, key: string, value: string]> {
  const out: Array<[keyof Tokens, string, string]> = [];
  const add = (group: keyof Tokens, entries: Record<string, string | number>, unit = '') => {
    for (const [key, value] of Object.entries(entries)) out.push([group, key, `${value}${unit}`]);
  };
  add('color', t.color);
  add('colorDark', t.colorDark);
  add('radius', t.radius, 'px');
  add('shadow', t.shadow);
  add('font', t.font);
  add('text', t.text, 'px');
  add('size', t.size, 'px');
  add('motion', t.motion, 'ms');
  return out;
}

/** A banner, then a rule block of declarations; LF endings, one trailing newline. */
export function block(selector: string, declarations: Declaration[]): string {
  const body = declarations.map(([name, value]) => `  ${name}: ${value};`).join('\n');
  return `${BANNER}\n${selector} {\n${body}\n}\n`;
}
